def cal_sum(n):
    # Base cases for Perrin sequence
    if n == 0:
        return 3
    elif n == 1:
        return 0
    elif n == 2:
        return 2

    # Initialize the first three terms of the Perrin sequence
    p0, p1, p2 = 3, 0, 2
    sum_perrin = p0 + p1 + p2

